import React, { useMemo, useState } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import Navbar from "../components/Navbar";
import { SERVICES } from "../constants/AppConstants";
import "./ServicesPage.css";

const ICONS = {
  dumbbell: "🏋️",
  calendar: "📅",
  printer: "🖨️",
  book: "📚",
  wallet: "👛",
  map: "🗺️",
};

const ROUTES = {
  gym: null,
  calendar: "/calendar",
  printing: null,
  library: null,
  wallet: "/wallet",
  map: "/map",
};

const CATEGORIES = ["All", "Academic", "Campus life", "Finance"];

const CATEGORY_MAP = {
  gym: "Campus life",
  calendar: "Academic",
  printing: "Academic",
  library: "Academic",
  wallet: "Finance",
  map: "Campus life",
};

export default function ServicesPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const [query, setQuery] = useState(params.get("q") || "");
  const [category, setCategory] = useState("All");

  const filtered = useMemo(() => {
    return SERVICES.filter((s) => {
      const matchesQuery = s.title.toLowerCase().includes(query.toLowerCase());
      const matchesCategory = category === "All" || CATEGORY_MAP[s.id] === category;
      return matchesQuery && matchesCategory;
    });
  }, [query, category]);

  function openService(service) {
    const route = ROUTES[service.id];
    if (route) navigate(route);
  }

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <div className="services-search">
          <input
            className="field"
            placeholder="Search ..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          <button className="btn btn-primary" onClick={() => {}}>Search</button>
        </div>

        <div className="services-toolbar">
          <h3>Our services:</h3>
          <select value={category} onChange={(e) => setCategory(e.target.value)}>
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>{c === "All" ? "filter by" : c}</option>
            ))}
          </select>
        </div>

        {filtered.length === 0 ? (
          <div className="services-empty">No services match "{query}".</div>
        ) : (
          <div className="services-grid">
            {filtered.map((s) => (
              <button key={s.id} className="service-card" onClick={() => openService(s)}>
                <div className="service-visual">{ICONS[s.icon]}</div>
                <div className="service-body">
                  <div className="service-title">{s.title}</div>
                  <div className="service-desc">{s.description}</div>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
